using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long k;
    cin >> n >> k;
    vector<long long> piles(n);
    for (int i = 0; i < n; i++) cin >> piles[i];

    if ((n - 1) % (k - 1) != 0) {
        cout << -1 << "\n";
    } else {
        priority_queue<long long, vector<long long>, greater<long long>> heap(piles.begin(), piles.end());
        long long cost = 0;
        while (heap.size() > 1) {
            long long merged = 0;
            for (long long t = 0; t < k; t++) {
                merged += heap.top();
                heap.pop();
            }
            cost += merged;
            heap.push(merged);
        }
        cout << cost << "\n";
    }

    return 0;
}

